func TestFilesService_AddFile_RetriesOnRateLimit(t *testing.T) {
	t.Parallel()

	tmp := filepath.Join(t.TempDir(), "report.txt")
	if err := os.WriteFile(tmp, []byte("document content"), 0o600); err != nil {
		t.Fatalf("write temp file: %v", err)
	}

	var calls int
	var bodies [][]byte
	client := newTestClientWithConfig(t, pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{
			MaxAttempts:     3,
			BaseDelay:       time.Millisecond,
			MaxDelay:        time.Millisecond,
			Jitter:          func(d time.Duration) time.Duration { return d },
			RetryAllMethods: true,
		},
	}, func(w http.ResponseWriter, r *http.Request) {
		calls++
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Fatalf("read request body: %v", err)
		}
		bodies = append(bodies, body)

		if calls == 1 {
			w.Header().Set("Retry-After", "0")
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"message":"rate limited"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"report.txt"}}`))
	})

	f, err := os.Open(tmp)
	if err != nil {
		t.Fatalf("open temp file: %v", err)
	}
	defer f.Close()

	file, err := client.Files.AddFile(context.Background(), "report.txt", f)
	if err != nil {
		t.Fatalf("AddFile error: %v", err)
	}
	if file.ID != 12 {
		t.Fatalf("unexpected file: %#v", file)
	}
	if calls != 2 {
		t.Fatalf("expected 2 attempts, got %d", calls)
	}
	if len(bodies) != 2 || !bytes.Equal(bodies[0], bodies[1]) {
		t.Fatalf("expected identical multipart bodies across attempts")
	}
}

