package multipartbody

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"mime/multipart"
)

// NewFile encodes src as a multipart/form-data body with a single file part.
//
// It returns the Content-Type header value and a reader over the encoded
// body. When src is an io.ReadSeeker (for example an *os.File), the encoded
// body wraps the source without copying it and can be rewound, so retried
// requests re-read the source from disk. Otherwise the encoded body is
// buffered and returned as a *bytes.Reader. Both forms are replayable by the
// SDK's retry transport, which makes retries (e.g. on 429 / 5xx) safe
// without any extra wiring.
func NewFile(fieldName, fileName string, src io.Reader) (string, io.Reader, error) {
	if fieldName == "" {
		return "", nil, fmt.Errorf("multipart field name is required")
	}
	if fileName == "" {
		return "", nil, fmt.Errorf("multipart file name is required")
	}
	if src == nil {
		return "", nil, fmt.Errorf("multipart file content is required")
	}

	if rs, ok := src.(io.ReadSeeker); ok {
		return newSeekableFile(fieldName, fileName, rs)
	}

	var buf bytes.Buffer
	writer := multipart.NewWriter(&buf)

	part, err := writer.CreateFormFile(fieldName, fileName)
	if err != nil {
		return "", nil, fmt.Errorf("create multipart file: %w", err)
	}
	if _, err := io.Copy(part, src); err != nil {
		return "", nil, fmt.Errorf("write multipart file: %w", err)
	}
	if err := writer.Close(); err != nil {
		return "", nil, fmt.Errorf("close multipart writer: %w", err)
	}

	return writer.FormDataContentType(), bytes.NewReader(buf.Bytes()), nil
}

func newSeekableFile(fieldName, fileName string, src io.ReadSeeker) (string, io.Reader, error) {
	start, err := src.Seek(0, io.SeekCurrent)
	if err != nil {
