// replayableSeekableBody returns a GetBody that replays a seekable request
// body from the position it had when the request was made, along with the
// remaining content length. It returns (nil, 0) when the body is not
// seekable or cannot be measured, leaving the request non-replayable.
func replayableSeekableBody(body io.ReadCloser) (func() (io.ReadCloser, error), int64) {
	if body == nil || body == http.NoBody {
		return nil, 0
	}
	rs, ok := body.(io.ReadSeeker)
	if !ok {
		return nil, 0
	}

	start, err := rs.Seek(0, io.SeekCurrent)
	if err != nil {
		return nil, 0
	}
	end, err := rs.Seek(0, io.SeekEnd)
	if err != nil || end < start {
		_, _ = rs.Seek(start, io.SeekStart)
		return nil, 0
	}
	if _, err := rs.Seek(start, io.SeekStart); err != nil {
		return nil, 0
	}

	return func() (io.ReadCloser, error) {
		if _, err := rs.Seek(start, io.SeekStart); err != nil {
			return nil, err
		}
		return io.NopCloser(rs), nil
	}, end - start
}

